import { SearchModal } from './components/SearchModal';
import { ProductCatalogPanel, ProductCardPanel } from './components/ProductCatalogPanel';
import { NewAnalysisModal } from './components/NewAnalysisModal';
import { DistributionPanel } from './components/DistributionPanel';
import { ListingPanel } from './components/ListingPanel';
import { StoresPanel } from './components/StoresPanel';
import { StoreAssignmentModal } from './components/StoreAssignmentModal';
import { MergeConfirmationModal } from './components/MergeConfirmationModal';
import { AnalysesPanel } from './components/AnalysesPanel';
import { ApiKeySelectionScreen } from './components/ApiKeySelectionScreen';
import { MissingPriceModal, MissingPriceItem } from './components/MissingPriceModal';
import Sidebar from './components/Sidebar';
import { GlobalAnalysisStatus } from './components/GlobalAnalysisStatus';
import { GalleryPanel } from './components/GalleryPanel';
import { CostPanel } from './components/CostPanel';
import { PromptManagerPanel } from './components/PromptManagerPanel';
import { PosMaterialPanel } from './components/PosMaterialPanel';
import { ModuleLandingPage } from './components/ModuleLandingPage';

export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
}

type ImageAction = 
  | { type: 'ADD_IMAGES'; payload: ImageState[] }
  | { type: 'SET_ANALYZING'; payload: string }
  | { type: 'SET_PENDING'; payload: string }
  | { type: 'SET_SUCCESS'; payload: { id: string; result: AnalysisResult; store?: Store; storeId?: number } }
  | { type: 'SET_ERROR'; payload: { id: string; error: string; needsAuthReset?: boolean } }
  | { type: 'UPDATE_PRICES'; payload: { imageId: string; productId: string; prices: PriceInfo[] }[] }
  | { type: 'RENAME_PRODUCT'; payload: { imageId: string; productId: string; newName: string } }
  | { type: 'CLEAR_ALL' };

function imageReducer(state: ImageState[], action: ImageAction): ImageState[] {
  switch (action.type) {
    case 'ADD_IMAGES': return [...action.payload, ...state];
    case 'SET_ANALYZING': return state.map(img => img.id === action.payload ? { ...img, status: 'analyzing' } : img);
    case 'SET_PENDING': return state.map(img => img.id === action.payload ? { ...img, status: 'pending', error: null } : img);
    case 'SET_SUCCESS': return state.map(img => img.id === action.payload.id ? { 
        ...img, status: 'success', analysisResult: action.payload.result,
        assignedStore: action.payload.store || img.assignedStore, assignedStoreId: action.payload.storeId || img.assignedStoreId
    } : img);
    case 'SET_ERROR': return state.map(img => img.id === action.payload.id ? { ...img, status: 'error', error: action.payload.error } : img);
    case 'UPDATE_PRICES': {
        return state.map(img => {
            const updates = action.payload.filter(u => u.imageId === img.id);
            if (!updates.length || !img.analysisResult) return img;
            const updatedProducts = img.analysisResult.products.map(p => {
                const update = updates.find(u => u.productId === p.id);
                return update ? { ...p, prices: update.prices } : p;
            });
            return { ...img, analysisResult: { ...img.analysisResult, products: updatedProducts } };
        });
    }
    case 'RENAME_PRODUCT': return state.map(img => img.id === action.payload.imageId ? {
        ...img, 
        analysisResult: img.analysisResult ? { 
            ...img.analysisResult, 
            products: img.analysisResult.products.map(p => p.id === action.payload.productId ? { ...p, name: action.payload.newName } : p)
        } : null
    } : img);
    case 'CLEAR_ALL': return [];
    default: return state;
  }
}

export const App: React.FC = () => {
  const [images, dispatch] = useReducer(imageReducer, []);
  const [selectedImageId, setSelectedImageId] = useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = useState<string | null>(null);
  const [sidebarView, setSidebarView] = useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = useState('');
  const deferredSearchTerm = useDeferredValue(productSearchTerm);
  const [highlightedProductName, setHighlightedProductName] = useState<string | null>(null);
  const [activeView, setActiveView] = useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = useState(false);
  const { t } = useTranslation();
  const [isAnalysisModalOpen, setIsAnalysisModalOpen] = useState(false); 
  const [pendingFiles, setPendingFiles] = useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = useState(false);
  const [brandsForClassification, setBrandsForClassification] = useState<string[]>([]);
  const [brandClassifications, setBrandClassifications] = useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = useState(false);
  const [activeAnalysis, setActiveAnalysis] = useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = useState(false); 
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  const isCurrentlyProcessingRef = useRef(false);

  useEffect(() => {
    const init = async () => {
        await seedDefaultPrompts(t);
        if ((window as any).aistudio) { 
            const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
            setHasApiKey(hasKey);
        }
    };
    init();
  }, [t]);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const handleStartAnalysis = useCallback(async (type: AnalysisType, model: string, fileList: FileList) => {
    const filesToProcess = Array.from(fileList);
    const tempImages: ImageState[] = await Promise.all(filesToProcess.map(async (file) => {
        const storeName = extractStoreFromFilename(file.name);
        let store: Store | null = null;
        if (storeName) {
             try { store = await findOrCreateStore({ name: storeName, chain: storeName.split(',')[0].trim(), city: '', address: '', code: '' }); } catch (e) {}
        }
        return {
            id: `${file.name}-${Date.now()}-${Math.random().toString(36).substring(7)}`,
            file, imageUrl: URL.createObjectURL(file), analysisResult: null, status: 'pending', error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type, retryCount: 0, assignedStore: store, assignedStoreId: store?.id
        };
    }));
    dispatch({ type: 'ADD_IMAGES', payload: tempImages });
  }, []);

  useEffect(() => {
    if (!isOnline || isCurrentlyProcessingRef.current) return;

    const next = images.find(img => img.status === 'pending');
    if (!next) return;

    const process = async () => {
        isCurrentlyProcessingRef.current = true;
        dispatch({ type: 'SET_ANALYZING', payload: next.id });

        try {
            const base64 = await fileToBase64(next.file);
            const catalog = await getCatalogEntries();
            const known = catalog.map(e => e.canonicalName).join(', ');
            const prompt = t(next.analysisType === 'price' ? 'geminiPromptPriceOnly' : next.analysisType === 'shelfShare' ? 'geminiPromptShelfShareOnly' : 'geminiPromptBoth').replace('{{knownProducts}}', known);

            const result = await analyzeImageWithGemini(base64, prompt, t('geminiSystemInstruction'), next.analysisType);

            const corrected = await Promise.all((result.products || []).map(async p => {
                const entry = await findProductByAlias(p.name);
                return { ...p, name: entry ? entry.canonicalName : p.name, isCorrected: !!entry, catalogProductId: entry?.id, id: `${next.id}-${Math.random()}` };
            }));

            const memory = await getBrandMemory();
            const memoryMap = new Map(memory.map(m => [m.brand, m.classification]));

            const newBrandsSet = new Set<string>();
            const updatedOur = new Set(brandClassifications.ourBrands);
            const updatedComp = new Set(brandClassifications.competitorBrands);

            corrected.forEach(p => {
                const b = getBrandFromName(p.name);
                if (!b) return;
                const remembered = memoryMap.get(b);
                if (remembered === 'our') updatedOur.add(b);
                else if (remembered === 'competitor') updatedComp.add(b);
                else if (!updatedOur.has(b) && !updatedComp.has(b)) newBrandsSet.add(b);
            });

            setBrandClassifications({ ourBrands: Array.from(updatedOur), competitorBrands: Array.from(updatedComp) });

            if (newBrandsSet.size > 0) {
                setBrandsForClassification(prev => Array.from(new Set([...prev, ...newBrandsSet])).sort());
                setIsBrandModalOpen(true);
            }

            dispatch({ type: 'SET_SUCCESS', payload: { id: next.id, result: { ...result, products: corrected } } });
        } catch (e: any) {
            const isAuth = e?.message?.includes('entity was not found');
            if (isAuth) setHasApiKey(false);
            dispatch({ type: 'SET_ERROR', payload: { id: next.id, error: isAuth ? t('apiKeyError') : t('failedToAnalyze') } });
        } finally {
            isCurrentlyProcessingRef.current = false;
        }
    };

    process();
  }, [images, isOnline, t, brandClassifications]);

  const productList = useMemo(() => {
    const completed = images.filter(img => img.status === 'success');
    if (!completed.length) return [];
    const map = new Map<string, { name: string; count: number; category: string }>();
    const knownNames: string[] = [];
    completed.forEach(img => {
      img.analysisResult?.products.forEach(p => {
        if (!p?.name) return;
        const matched = findBestMatch(p.name, knownNames) || p.name;
        if (!knownNames.includes(matched)) knownNames.push(matched);
        const entry = map.get(matched);
        if (entry) entry.count++;
        else map.set(matched, { name: matched, count: 1, category: getCategoryFromName(matched, t('unassignedCategory')) });
      });
    });
    const result = Array.from(map.values()).sort((a, b) => a.category.localeCompare(b.category) || b.count - a.count);
    return deferredSearchTerm ? result.filter(p => p.name.toLowerCase().includes(deferredSearchTerm.toLowerCase())) : result;
  }, [images, t, deferredSearchTerm]);

  const brandProductsMap = useMemo(() => {
    const map: Record<string, string[]> = {};
    images.forEach(img => {
      img.analysisResult?.products.forEach(p => {
        if (!p || !p.name) return;
        const b = p.brand || getBrandFromName(p.name);
        if (b) {
          if (!map[b]) map[b] = [];
          if (!map[b].includes(p.name)) map[b].push(p.name);
        }
      });
    });
    return map;
  }, [images]);

  const handleNavClick = useCallback((v: ActiveView) => {
    setActiveView(v);
    if (v !== 'home' && images.length) { setSelectedImageId(null); setSelectedProductName(null); setHighlightedProductName(null); }
  }, [images.length]);

  const handleConfirmBrands = useCallback((newlyClassified: BrandClassifications) => {
    setBrandClassifications(prev => ({
      ourBrands: Array.from(new Set([...prev.ourBrands, ...newlyClassified.ourBrands])),
      competitorBrands: Array.from(new Set([...prev.competitorBrands, ...newlyClassified.competitorBrands]))
    }));
    setIsBrandModalOpen(false);
    setBrandsForClassification([]);
  }, []);

  const handleSaveAnalysis = useCallback(async () => {
    if (!activeAnalysis) return;
    try {
        const inputRateOverride = await getSetting('inputTokenRate', 0.15);
        const outputRateOverride = await getSetting('outputTokenRate', 0.60);

        let totalInput = 0;
        let totalOutput = 0;
        let totalCost = 0;
        const mainModel = 'gemini-2.5-flash';

        const serializableImages: SerializableImageState[] = await Promise.all(
          images.map(async (image) => {
            const base64Data = await fileToBase64(image.file);
            if (image.analysisResult?.usageMetadata) {
                const meta = image.analysisResult.usageMetadata;
                totalInput += meta.promptTokenCount;
                totalOutput += meta.candidatesTokenCount;

                const pricing = MODEL_PRICING_TABLE[mainModel] || MODEL_PRICING_TABLE['gemini-2.5-flash'];
                totalCost += (meta.promptTokenCount / 1000000) * inputRateOverride;
                totalCost += (meta.candidatesTokenCount / 1000000) * outputRateOverride;
            }
            return {
              id: image.id,
              file: { name: image.file.name, type: image.file.type, lastModified: image.file.lastModified, data: base64Data },
              imageUrl: '', analysisResult: image.analysisResult, status: image.status, error: image.error,
              uploadDate: image.uploadDate.toISOString(), analysisType: image.analysisType, retryCount: image.retryCount,
              assignedStore: image.assignedStore, assignedStoreId: image.assignedStoreId
            };
          })
        );

        const updatedAnalysis: Analysis = {
          ...activeAnalysis,
          images: serializableImages,
          brandClassifications: brandClassifications,
          storeId: serializableImages[0]?.assignedStoreId,
          costInfo: {
              inputTokens: totalInput,
              outputTokens: totalOutput,
              cost: totalCost,
              modelName: mainModel
          }
        };

        await saveAnalysis(updatedAnalysis);
        setActiveAnalysis(updatedAnalysis);
    } catch (e) {
        console.error("Failed to save analysis:", e);
        alert(t('archiveSaveError'));
    }
  }, [activeAnalysis, images, brandClassifications, t]);

  const handleLoadAnalysis = useCallback(async (analysisId: string) => {
    try {
        const analysisToLoad = await loadAnalysis(analysisId);
        if (analysisToLoad) {
          images.forEach(img => URL.revokeObjectURL(img.imageUrl));
          dispatch({ type: 'CLEAR_ALL' });
          const loadedImages: ImageState[] = analysisToLoad.images.map(s => {
            const file = base64ToFile(s.file.data, s.file.name, s.file.type, s.file.lastModified);
            return {
              ...s,
              file,
              imageUrl: URL.createObjectURL(file),
              uploadDate: new Date(s.uploadDate),
              status: s.status || 'success', 
              analysisType: (s.analysisType || 'both') as AnalysisType,
              retryCount: s.retryCount || 0
            };
          });
          setActiveAnalysis(analysisToLoad);
          dispatch({ type: 'ADD_IMAGES', payload: loadedImages });
          setBrandClassifications(analysisToLoad.brandClassifications || { ourBrands: [], competitorBrands: [] });
          setIsSearchModalOpen(false);
          setActiveView('priceMonitoring');
        }
    } catch (e) {
        console.error("Failed to load analysis:", e);
        alert(t('archiveLoadError'));
    }
  }, [images, t]);

  const endCurrentAnalysisWithoutSaving = useCallback(() => {
    images.forEach(img => URL.revokeObjectURL(img.imageUrl));
    dispatch({ type: 'CLEAR_ALL' });
    setSelectedImageId(null);
    setSelectedProductName(null);
    setHighlightedProductName(null);
    setProductSearchTerm('');
    setBrandClassifications({ ourBrands: [], competitorBrands: [] });
    setActiveAnalysis(null);
    setActiveView('home');
  }, [images]);

  const endCurrentAnalysisAndSave = useCallback(async () => {
    if (activeAnalysis) {
        await handleSaveAnalysis();
    }
    endCurrentAnalysisWithoutSaving();
  }, [activeAnalysis, handleSaveAnalysis, endCurrentAnalysisWithoutSaving]);

  if (!hasApiKey) return <ApiKeySelectionScreen onSelectApiKey={handleSelectApiKey} />;

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col antialiased">
      <Header onNewAnalysis={() => activeAnalysis ? setIsClearConfirmOpen(true) : setIsNewAnalysisModalOpen(true)} onOpenSearch={() => setIsSearchModalOpen(true)} />
      <GlobalAnalysisStatus total={images.length} completed={images.filter(i => i.status === 'success').length} analyzing={images.filter(i => i.status === 'analyzing').length} errors={images.filter(i => i.status === 'error').length} />
      <div className="flex flex-1 overflow-hidden">
        <Sidebar activeView={activeView} onNavClick={handleNavClick} />
        <div className="flex-1 p-6 overflow-y-auto scroll-smooth custom-scrollbar">
          {activeView === 'home' ? <HomeScreen onStartAnalysis={() => setIsNewAnalysisModalOpen(true)} /> :
           activeView === 'analyses' ? <AnalysesPanel onNewAnalysis={() => setIsNewAnalysisModalOpen(true)} onLoadAnalysis={handleLoadAnalysis} /> :
           activeView === 'stores' ? <StoresPanel /> :
           activeView === 'gallery' ? <GalleryPanel /> :
           activeView === 'posMaterial' ? <PosMaterialPanel /> :
           activeView === 'productCatalog' ? (selectedCatalogProduct ? <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} /> : <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />) :
           activeView === 'distribution' ? <DistributionPanel activeImages={images} /> :
           activeView === 'costs' ? <CostPanel /> :
           activeView === 'prompts' ? <PromptManagerPanel /> :
           images.length === 0 && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') ? 
           <ModuleLandingPage type={activeView} onStart={() => setIsNewAnalysisModalOpen(true)} onLoad={() => setActiveView('analyses')} /> :
           images.length === 0 ? <div className="h-full flex items-center justify-center"><ImageUploader onImageUpload={(f) => { setPendingFiles(f); setIsAnalysisModalOpen(true); }} isLoading={images.some(i => i.status === 'analyzing')} /></div> :
           <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-8">
             <aside className="lg:col-span-1 bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col gap-4 self-start no-print">
               <div className="flex justify-between items-center px-1">
                 <h3 className="font-black text-gray-900 uppercase text-xs tracking-widest">{sidebarView === 'images' ? t('images') : t('products')}</h3>
                 <div className="flex gap-2 bg-gray-100 p-1 rounded-lg">
                   <button onClick={() => setSidebarView('images')} className={`p-1.5 rounded-md transition-all ${sidebarView === 'images' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-400'}`}><AppIcon className="w-4 h-4"/></button>
                   <button onClick={() => setSidebarView('products')} className={`p-1.5 rounded-md transition-all ${sidebarView === 'products' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-400'}`}><CircleStackIcon className="w-4 h-4"/></button>
                 </div>
               </div>
               <div className="relative px-1">
                   <input type="text" className="w-full bg-gray-50 border-none rounded-xl text-[11px] p-2 pr-8 focus:ring-1 focus:ring-lime-500" placeholder={sidebarView === 'images' ? t('searchImages') : t('searchProduct')} value={productSearchTerm} onChange={e => setProductSearchTerm(e.target.value)} />
               </div>
               <div className="max-h-[calc(100vh-360px)] overflow-y-auto space-y-2 custom-scrollbar pr-1">
                 {sidebarView === 'images' ? 
                   images.map(img => (
                     <div key={img.id} onClick={() => { setSelectedImageId(img.id); setSelectedProductName(null); }} className={`flex gap-3 p-2 rounded-xl cursor-pointer border transition-all duration-200 ${selectedImageId === img.id ? 'bg-lime-50 border-lime-400 scale-[1.02] shadow-sm shadow-lime-100' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                       <img src={img.imageUrl} className="w-10 h-10 object-cover rounded-lg bg-gray-100" />
                       <div className="min-w-0 flex-1">
                         <p className="text-[11px] font-bold truncate text-gray-800">{img.file.name}</p>
                         <p className="text-[9px] font-black uppercase text-gray-400">{img.status === 'analyzing' ? t('analyzing') : img.uploadDate.toLocaleDateString()}</p>
                       </div>
                       {img.status === 'success' && <div className="h-1.5 w-1.5 rounded-full bg-green-500 mt-2"></div>}
                     </div>
                   )) : 
                   productList.map(p => (
                     <button key={p.name} onClick={() => { setSelectedProductName(p.name); setSelectedImageId(null); }} className={`flex justify-between w-full p-3 rounded-xl border text-left transition-all duration-200 ${selectedProductName === p.name ? 'bg-lime-50 border-lime-400 shadow-sm shadow-lime-100' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                       <span className="text-[11px] font-bold truncate pr-2 text-gray-700">{p.name}</span>
                       <span className="text-[11px] font-black text-lime-600 bg-lime-100/50 px-2 py-0.5 rounded-lg">{p.count}</span>
                     </button>
                   ))
                 }
               </div>
               <button onClick={() => setIsImageUploadOverlayOpen(true)} className="w-full py-3 bg-lime-600 text-white rounded-xl text-xs font-black uppercase tracking-widest flex justify-center items-center gap-2 hover:bg-lime-700 transition-all shadow-lg shadow-lime-100 active:scale-95"><UploadIcon className="w-4 h-4"/>{t('addMoreImages')}</button>
             </aside>
             <main className="lg:col-span-3 flex flex-col gap-6">
                {!selectedImageId && !selectedProductName && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') && 
                  <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={endCurrentAnalysisAndSave} initialView={activeView as any} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />}
                {selectedImageId && images.find(i => i.id === selectedImageId) && <>
                  <ImageAnalysisDisplay imageUrl={images.find(i => i.id === selectedImageId)!.imageUrl} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                  <ResultsPanel imageId={selectedImageId} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} error={images.find(i => i.id === selectedImageId)!.error} onReset={endCurrentAnalysisAndSave} onProductNameUpdate={async (i, pid, o, n) => { await addOrUpdateProductCorrection(o, n); dispatch({type:'RENAME_PRODUCT', payload:{imageId:i, productId:pid, newName:n}}); }} onRetry={() => dispatch({type:'SET_PENDING', payload:selectedImageId})} />
                </>}
                {selectedProductName && <ProductSummaryPanel productName={selectedProductName} images={images} onReset={endCurrentAnalysisAndSave} onImageSelect={(id, name) => { setSelectedImageId(id); setSelectedProductName(null); setHighlightedProductName(name); }} />}
             </main>
           </div>
          }
        </div>
      </div>
      <div className="modal-root">
        <NewAnalysisModal isOpen={isNewAnalysisModalOpen} onClose={() => setIsNewAnalysisModalOpen(false)} onConfirm={async (n, t, m, f) => { const a = { id: `analysis-${Date.now()}`, name: n, createdAt: new Date().toISOString(), images: [], store: null }; await db.analyses.add(a); setActiveAnalysis(a); setActiveView('priceMonitoring'); handleStartAnalysis(t, m, f); setIsNewAnalysisModalOpen(false); }} initialFiles={pendingFiles} />
        <AnalysisTypeModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} onSelect={async type => { if (pendingFiles) handleStartAnalysis(type, 'gemini-2.5-flash', pendingFiles); setIsAnalysisModalOpen(false); }} />
        <ClearConfirmModal isOpen={isClearConfirmOpen} onClose={() => setIsClearConfirmOpen(false)} onConfirmDelete={endCurrentAnalysisWithoutSaving} onSaveToArchive={endCurrentAnalysisAndSave} />
        <BrandDefinitionModal isOpen={isBrandModalOpen} onClose={() => setIsBrandModalOpen(false)} onConfirm={handleConfirmBrands} allBrands={brandsForClassification} brandProductsMap={brandProductsMap} />
        <SearchModal isOpen={isSearchModalOpen} onClose={() => setIsSearchModalOpen(false)} onLoadAnalysis={handleLoadAnalysis} />
        <MissingPriceModal isOpen={isMissingPriceModalOpen} onClose={() => setIsMissingPriceModalOpen(false)} items={images.flatMap(img => (img.analysisResult?.products || []).filter(p => !p.prices?.length).map(p => ({ imageId: img.id, productId: p.id, name: p.name, imageUrl: img.imageUrl })))} onSave={updates => dispatch({type:'UPDATE_PRICES', payload: updates})} />
        {isImageUploadOverlayOpen && <div className="fixed inset-0 bg-gray-800/75 flex items-center justify-center z-50 p-4 animate-fade-in"><div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-2xl overflow-hidden"><div className="p-6 border-b flex justify-between items-center bg-gray-50"><h2 className="text-sm font-black uppercase tracking-widest flex items-center gap-2 text-gray-700"><UploadIcon className="w-5 h-5 text-lime-600" />{t('uploadMoreImagesTitle')}</h2><button onClick={() => setIsImageUploadOverlayOpen(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-400"><CloseIcon className="w-5 h-5"/></button></div><div className="p-10"><ImageUploader onImageUpload={(f) => { setPendingFiles(f); setIsAnalysisModalOpen(true); setIsImageUploadOverlayOpen(false); }} isLoading={images.some(i => i.status === 'analyzing')} /></div></div></div>}
      </div>
    </div>
  );
};

export default App;

export interface BoundingBox {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface PriceInfo {
  value: string;
  type: string;
}

export type ObjectType = 'product' | 'pos_material';
export type PosType = 'wobbler' | 'stopper' | 'stand' | 'pallet' | 'secondary_display';

export interface DetectedProduct {
  id: string;
  imageId?: string;
  name: string;
  brand?: string;
  prices?: PriceInfo[];
  boundingBox: BoundingBox;
  confidence: number;
