import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { getAnalyses, getCatalogProductNames, saveDistributionReport, getDistributionReports, deleteDistributionReport, getStores } from '../db.ts';
import { DetectedProduct, DistributionMatrix, DistributionRow, DistributionReport, DistributionCell, Store } from '../types.ts';
import { normalizeProductName, removeDateFromStoreName, findBestMatch } from '../utils/helpers.ts';
import { exportDistributionToXLS } from '../utils/export.ts';
// FIX: Re-importing icons to ensure all exports are recognized. The issue appears to be with module resolution, not the import path or component names themselves.
import { TableCellsIcon, CheckCircleIcon, XCircleIcon, FunnelIcon, CalculatorIcon, SpinnerIcon, ArrowDownTrayIcon, SaveIcon, FolderOpenIcon, TrashIcon, CloseIcon } from './Icons.tsx';
import type { ImageState } from '../App.tsx';

interface DistributionPanelProps {
    activeImages?: ImageState[];
}

export const DistributionPanel: React.FC<DistributionPanelProps> = ({ activeImages = [] }) => {
    const { t } = useTranslation();
    const [allCatalogProducts, setAllCatalogProducts] = useState<string[]>([]);
    const [selectedProducts, setSelectedProducts] = useState<string[]>([]);
    const [matrix, setMatrix] = useState<DistributionMatrix | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [isCalculating, setIsCalculating] = useState(false);

    // Report Management States
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [isLoadModalOpen, setIsLoadModalOpen] = useState(false);
    const [newReportName, setNewReportName] = useState('');
    const [savedReports, setSavedReports] = useState<DistributionReport[]>([]);

    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            const products = await getCatalogProductNames();
            setAllCatalogProducts(products.sort());

            // AUTOMATIC PRE-SELECTION: If no products are selected and we have active images, pre-select items found in current batch
            if (selectedProducts.length === 0 && activeImages.length > 0) {
                const foundInCurrent = new Set<string>();
                activeImages.forEach(img => {
                    img.analysisResult?.products.forEach(p => {
                        if (p.name) foundInCurrent.add(p.name);
                    });
                });

                if (foundInCurrent.size > 0) {
                    const toSelect = products.filter(p => foundInCurrent.has(p));
                    if (toSelect.length > 0) {
                        setSelectedProducts(toSelect);
                    }
                }
            }
            setIsLoading(false);
        };
        loadData();
    }, [activeImages.length]);

    // Sledovanie úspešne analyzovaných obrázkov
    const successfulActiveCount = useMemo(() => 
        activeImages.filter(img => img.status === 'success').length, 
    [activeImages]);

    // Automatický prepočet pri zmene vstupných dát alebo dokončení analýzy fotky
    useEffect(() => {
        if (selectedProducts.length > 0) {
            generateMatrix();
        } else {
            setMatrix(null);
        }
    }, [selectedProducts, successfulActiveCount]);

    const toggleProductSelection = (product: string) => {
        setSelectedProducts(prev => 
            prev.includes(product) 
                ? prev.filter(p => p !== product)
                : [...prev, product]
        );
    };

    const selectAll = () => setSelectedProducts(allCatalogProducts);
    const deselectAll = () => setSelectedProducts([]);

    const generateMatrix = async () => {
        if (selectedProducts.length === 0) return;
        setIsCalculating(true);

        try {
            const archivedAnalyses = await getAnalyses();
            const allStores = await getStores();
            const storesMap = new Map<number, Store>(allStores.map(s => [s.id!, s]));

            // Map: UniqueIdentifier -> { name, code, products: Map<CanonicalProductName, MaxConfidence> }
            const storeInventory = new Map<string, { name: string, code?: string, products: Map<string, number> }>();

            // 1. PRE-FILL: Initialize inventory for ALL known stores from DB
            allStores.forEach(store => {
                const uniqueKey = `ID_${store.id}`;
                let displayName = store.name;
                storeInventory.set(uniqueKey, { name: displayName, code: store.code, products: new Map() });
            });

            // 2. LIVE: Process AKTÍVNYCH dát z prebiehajúcej analýzy (LIVE)
            activeImages.forEach(img => {
                if (img.status !== 'success' || !img.analysisResult) return;

                let uniqueKey = '';
                if (img.assignedStoreId) {
                    uniqueKey = `ID_${img.assignedStoreId}`;
                } else if (img.analysisResult.storeInfo) {
                    const chain = removeDateFromStoreName(img.analysisResult.storeInfo.chain);
                    uniqueKey = `RAW_${chain}`;
                }

                if (!uniqueKey) return;
                if (!storeInventory.has(uniqueKey)) {
                    storeInventory.set(uniqueKey, { 
                        name: uniqueKey.replace('RAW_', ''), 
                        products: new Map() 
                    });
                }

                const inventory = storeInventory.get(uniqueKey)!;
                img.analysisResult.products.forEach(p => {
                    if (p.confidence < 0.7) return;
                    const matchedName = findBestMatch(p.name, selectedProducts);
                    if (matchedName) {
                        const current = inventory.products.get(matchedName) || 0;
                        inventory.products.set(matchedName, Math.max(current, p.confidence));
                    }
                });
            });

            // 3. ARCHIVE: Spracovanie ARCHÍVNYCH dát
            archivedAnalyses.forEach(analysis => {
                analysis.images.forEach(img => {
                    if (!img.analysisResult) return;

                    let uniqueKey = '';
                    if (img.assignedStoreId) {
                        uniqueKey = `ID_${img.assignedStoreId}`;
                    } else if (img.analysisResult.storeInfo) {
                        const chain = removeDateFromStoreName(img.analysisResult.storeInfo.chain);
                        uniqueKey = `RAW_${chain}`;
                    }

                    if (!uniqueKey || !storeInventory.has(uniqueKey)) return;

                    const inventory = storeInventory.get(uniqueKey)!;
                    img.analysisResult.products.forEach(p => {
                        const matchedName = findBestMatch(p.name, selectedProducts);
                        if (matchedName) {
                            const current = inventory.products.get(matchedName) || 0;
                            inventory.products.set(matchedName, Math.max(current, p.confidence));
                        }
                    });
                });
            });

            // 4. Budovanie riadkov matice
            const rows: DistributionRow[] = [];
            const columnCounts: Record<string, number> = {};
            selectedProducts.forEach(p => columnCounts[p] = 0);

            for (const [key, data] of storeInventory.entries()) {
                const presenceRecord: Record<string, DistributionCell> = {};
                let presentCount = 0;

                selectedProducts.forEach(targetProduct => {
                    const maxConfidence = data.products.get(targetProduct) || 0;
                    const isPresent = maxConfidence > 0;

                    // FIX: Added missing isPresent property to match DistributionCell interface
                    presenceRecord[targetProduct] = { isPresent, count: isPresent ? 1 : 0, maxConfidence };
                    if (isPresent) {
                        presentCount++;
                        columnCounts[targetProduct]++;
                    }
                });

                const fulfillment = selectedProducts.length > 0 ? (presentCount / selectedProducts.length) * 100 : 0;

                if (presentCount > 0 || key.startsWith('ID_')) { // Zobrazujeme predajne s výskytom alebo tie z DB
                    rows.push({
                        storeName: data.name,
                        storeId: key.startsWith('ID_') ? parseInt(key.split('_')[1]) : undefined,
                        storeCode: data.code,
                        presence: presenceRecord,
                        totalFacings: presentCount,
                        fulfillment
                    });
                }
            }

            rows.sort((a, b) => b.fulfillment - a.fulfillment || a.storeName.localeCompare(b.storeName));

            const columnSummaries: Record<string, number> = {};
            selectedProducts.forEach(p => {
                columnSummaries[p] = rows.length > 0 ? (columnCounts[p] / rows.length) * 100 : 0;
            });

            setMatrix({ rows, columnSummaries, selectedEntities: selectedProducts, mode: 'sku' });
        } catch (error) {
            console.error("Distribution error:", error);
        } finally {
            setIsCalculating(false);
        }
    };

    const handleExport = () => {
        if (matrix) exportDistributionToXLS(matrix, t);
    };

    const openSaveModal = () => {
        const today = new Date();
        const defaultName = `${t('distributionModule')} - ${today.getDate()}.${today.getMonth() + 1}.${today.getFullYear()}`;
        setNewReportName(defaultName);
        setIsSaveModalOpen(true);
    };

    const handleSaveReport = async () => {
        if (!newReportName.trim()) return;
        await saveDistributionReport({
            name: newReportName.trim(),
            createdAt: new Date().toISOString(),
            selectedProducts: selectedProducts
        });
        setIsSaveModalOpen(false);
    };

    const openLoadModal = async () => {
        const reports = await getDistributionReports();
        setSavedReports(reports);
        setIsLoadModalOpen(true);
    };

    const handleLoadReport = (report: DistributionReport) => {
        setSelectedProducts(report.selectedProducts);
        setIsLoadModalOpen(false);
    };

    const handleDeleteReport = async (id?: number) => {
        if (id && window.confirm(t('deleteReportConfirm'))) {
             await deleteDistributionReport(id);
             const reports = await getDistributionReports();
             setSavedReports(reports);
        }
    };

    const renderCell = (cell?: DistributionCell) => {
        if (cell?.count && cell.count > 0) {
            return (
                <div className="flex items-center justify-center h-full" title={`${t('presenceYes')} (${Math.round(cell.maxConfidence * 100)}%)`}>
                    <CheckCircleIcon className="w-5 h-5 text-green-600" />
                </div>
            );
        }
        return (
            <div className="flex items-center justify-center h-full" title={t('presenceNo')}>
                <XCircleIcon className="w-5 h-5 text-red-100" />
            </div>
        );
    };

    return (
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col max-w-[98vw] mx-auto">
             {/* Save Modal */}
            {isSaveModalOpen && (
                <div className="fixed inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center z-50 p-4">
                     <div className="bg-white rounded-lg shadow-xl w-full max-w-md p-6">
                        <h3 className="text-lg font-bold mb-4">{t('saveReportTitle')}</h3>
                        <input 
                            type="text" 
                            value={newReportName} 
                            onChange={(e) => setNewReportName(e.target.value)}
                            className="w-full border rounded p-2 mb-4 bg-white text-gray-900"
                            placeholder={t('reportNamePlaceholder')}
                        />
                        <div className="flex justify-end gap-2">
                            <button onClick={() => setIsSaveModalOpen(false)} className="px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 text-gray-700">{t('cancelButton')}</button>
                            <button onClick={handleSaveReport} className="px-4 py-2 bg-lime-600 text-white rounded hover:bg-lime-700">{t('save')}</button>
                        </div>
                     </div>
                </div>
            )}

             {/* Load Modal */}
             {isLoadModalOpen && (
                <div className="fixed inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center z-50 p-4">
                     <div className="bg-white rounded-lg shadow-xl w-full max-w-md p-6 flex flex-col max-h-[80vh]">
                        <div className="flex justify-between items-center mb-4">
                             <h3 className="text-lg font-bold text-gray-900">{t('savedReports')}</h3>
                             <button onClick={() => setIsLoadModalOpen(false)}><CloseIcon className="w-5 h-5 text-gray-500" /></button>
                        </div>
                        <div className="flex-grow overflow-y-auto space-y-2">
                            {savedReports.length === 0 ? (
                                <p className="text-center text-gray-500 py-10">{t('noSavedReports')}</p>
                            ) : (
                                savedReports.map(report => (
                                    <div key={report.id} className="flex items-center justify-between p-3 bg-gray-50 rounded hover:bg-gray-100 transition-colors border border-gray-200">
                                        <div className="min-w-0">
                                            <p className="font-medium text-gray-900 truncate">{report.name}</p>
                                            <p className="text-[10px] text-gray-500">{new Date(report.createdAt).toLocaleDateString()} | {report.selectedProducts.length} SKU</p>
                                        </div>
                                        <div className="flex gap-1">
                                            <button onClick={() => handleLoadReport(report)} className="p-2 text-blue-600 hover:bg-blue-100 rounded-full" title={t('load')}><FolderOpenIcon className="w-4 h-4" /></button>
                                            <button onClick={() => handleDeleteReport(report.id)} className="p-2 text-red-600 hover:bg-red-100 rounded-full" title={t('delete')}><TrashIcon className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                     </div>
                </div>
            )}

            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 mb-6">
                <div>
                    <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                        <TableCellsIcon className="w-6 h-6 text-lime-600" />
                        {t('distributionModule')}
                    </h2>
                    {successfulActiveCount > 0 && (
                        <p className="text-xs text-lime-600 font-bold mt-1">
                            LIVE: {t('analyzed')}: {successfulActiveCount}
                        </p>
                    )}
                </div>
                <div className="flex flex-wrap gap-2">
                    <button onClick={openLoadModal} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-md bg-gray-100 text-gray-700 hover:bg-gray-200">
                        <FolderOpenIcon className="w-4 h-4" /> {t('savedReports')}
                    </button>
                    {selectedProducts.length > 0 && (
                        <button onClick={openSaveModal} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-md bg-gray-100 text-gray-700 hover:bg-gray-200">
                            <SaveIcon className="w-4 h-4" /> {t('saveReport')}
                        </button>
                    )}
                    {matrix && (
                         <button onClick={handleExport} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-md bg-blue-600 text-white hover:bg-blue-700">
                            <ArrowDownTrayIcon className="w-4 h-4" /> {t('exportToXLS')}
                        </button>
                    )}
                </div>
            </div>

            {/* Product Selector */}
            <div className="bg-gray-50 p-4 rounded-xl mb-6">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-sm font-black text-gray-700 uppercase tracking-widest flex items-center gap-2">
                        <FunnelIcon className="w-4 h-4" /> {t('selectProducts')}
                    </h3>
                    <div className="flex gap-4">
                        <button onClick={selectAll} className="text-xs font-bold text-lime-700 hover:underline uppercase">{t('selectAll')}</button>
                        <button onClick={deselectAll} className="text-xs font-bold text-gray-400 hover:underline uppercase">{t('deselectAll')}</button>
                    </div>
                </div>
                <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto pr-2">
                    {allCatalogProducts.map(p => (
                        <button
                            key={p}
                            onClick={() => toggleProductSelection(p)}
                            className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all border-2 ${
                                selectedProducts.includes(p)
                                ? 'bg-lime-600 border-lime-600 text-white shadow-md'
                                : 'bg-white border-gray-200 text-gray-600 hover:border-lime-300'
                            }`}
                        >
                            {p}
                        </button>
                    ))}
                </div>
            </div>

            {/* Matrix Result */}
            {isCalculating ? (
                <div className="flex-grow flex flex-col items-center justify-center py-20">
                    <SpinnerIcon className="w-10 h-10 text-lime-500 animate-spin" />
                    <p className="mt-4 text-sm font-bold text-gray-500">{t('calculating')}</p>
                </div>
            ) : matrix ? (
                <div className="flex-grow overflow-x-auto border border-gray-100 rounded-xl">
                    <table className="min-w-full divide-y divide-gray-200 border-collapse">
                        <thead className="bg-gray-800 text-white sticky top-0 z-10">
                            <tr>
                                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-wider min-w-[200px] sticky left-0 bg-gray-800 border-r border-gray-700">
                                    {t('storeName')}
                                </th>
                                {matrix.selectedEntities.map(p => (
                                    <th key={p} className="px-2 py-3 text-center text-[10px] font-black uppercase tracking-tighter min-w-[80px] border-l border-gray-700">
                                        <div className="truncate max-w-[120px] mx-auto" title={p}>{p}</div>
                                    </th>
                                ))}
                                <th className="px-4 py-3 text-center text-[10px] font-black uppercase tracking-wider bg-lime-700 min-w-[80px]">
                                    {t('storeFulfillment')}
                                </th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-100">
                            {matrix.rows.map((row, idx) => (
                                <tr key={idx} className="hover:bg-lime-50/50 transition-colors">
                                    <td className="px-4 py-3 text-xs font-bold text-gray-900 sticky left-0 bg-white border-r border-gray-100 shadow-[2px_0_5px_rgba(0,0,0,0.03)]">
                                        {row.storeName}
                                        {row.storeCode && <span className="ml-2 text-[10px] bg-blue-100 text-blue-700 px-1 rounded">#{row.storeCode}</span>}
                                    </td>
                                    {matrix.selectedEntities.map(p => (
                                        <td key={p} className="px-2 py-3 text-center border-l border-gray-50">
                                            {renderCell(row.presence[p])}
                                        </td>
                                    ))}
                                    <td className="px-4 py-3 text-center text-xs font-black text-lime-800 bg-lime-50/50">
                                        {Math.round(row.fulfillment)}%
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                        <tfoot className="bg-gray-100 font-bold border-t-2 border-gray-200">
                            <tr>
                                <td className="px-4 py-3 text-[10px] uppercase font-black text-gray-500 sticky left-0 bg-gray-100 border-r border-gray-200">
                                    {t('distributionShare')}
                                </td>
                                {matrix.selectedEntities.map(p => (
                                    <td key={p} className="px-2 py-3 text-center text-xs text-lime-700 border-l border-gray-200">
                                        {Math.round(matrix.columnSummaries[p])}%
                                    </td>
                                ))}
                                <td className="bg-lime-100"></td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            ) : (
                <div className="flex-grow flex flex-col items-center justify-center py-20 text-center">
                    <TableCellsIcon className="w-16 h-16 text-gray-200 mb-4" />
                    <p className="text-gray-400 font-medium italic">{t('selectProductsAndCalculate')}</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { getAnalyses, getCatalogProductNames, saveDistributionReport, getDistributionReports, deleteDistributionReport, getStores } from '../db.ts';
import { DetectedProduct, DistributionMatrix, DistributionRow, DistributionReport, DistributionCell, Store } from '../types.ts';
import { normalizeProductName, removeDateFromStoreName, findBestMatch } from '../utils/helpers.ts';
import { exportDistributionToXLS } from '../utils/export.ts';
import { 
    TableCellsIcon, 
    CheckCircleIcon, 
    XCircleIcon, 
    FunnelIcon, 
    CalculatorIcon, 
    SpinnerIcon, 
    ArrowDownTrayIcon, 
    SaveIcon, 
    FolderOpenIcon, 
    TrashIcon, 
    CloseIcon,
    ArrowPathIcon,
    WarningIcon
} from './Icons.tsx';
import type { ImageState } from '../App.tsx';

interface DistributionPanelProps {
    activeImages?: ImageState[];
}

export const DistributionPanel: React.FC<DistributionPanelProps> = ({ activeImages = [] }) => {
    const { t } = useTranslation();
    const [allCatalogProducts, setAllCatalogProducts] = useState<string[]>([]);
    const [selectedProducts, setSelectedProducts] = useState<string[]>([]);
    const [matrix, setMatrix] = useState<DistributionMatrix | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [isCalculating, setIsCalculating] = useState(false);

    // Report Management States
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [isLoadModalOpen, setIsLoadModalOpen] = useState(false);
    const [newReportName, setNewReportName] = useState('');
    const [savedReports, setSavedReports] = useState<DistributionReport[]>([]);

    // Sledovanie úspešne analyzovaných obrázkov
    const successfulActiveCount = useMemo(() => 
        activeImages.filter(img => img.status === 'success').length, 
    [activeImages]);

    const isAnyActiveAnalyzing = useMemo(() => 
        activeImages.some(img => img.status === 'analyzing' || img.status === 'pending'),
    [activeImages]);

    // 1. Načítanie katalógu a automatický výber pri štarte alebo novom úspešnom výsledku
    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            const products = await getCatalogProductNames();
            setAllCatalogProducts(products.sort());

            // Ak nemáme nič vybrané, skúsime vybrať produkty, ktoré sú v aktuálnej dávke
            if (selectedProducts.length === 0 && successfulActiveCount > 0) {
                const foundInCurrent = new Set<string>();
                activeImages.forEach(img => {
                    if (img.status === 'success' && img.analysisResult?.products) {
                        img.analysisResult.products.forEach(p => {
                            if (p.name) foundInCurrent.add(p.name);
                        });
                    }
                });

                if (foundInCurrent.size > 0) {
                    const toSelect = products.filter(p => foundInCurrent.has(p));
                    if (toSelect.length > 0) {
                        setSelectedProducts(toSelect);
                    }
                }
            }
            setIsLoading(false);
        };
        loadData();
    }, [successfulActiveCount]);

    // 2. Automatický prepočet matice pri zmene výberu alebo nových dátach
    useEffect(() => {
        if (selectedProducts.length > 0) {
            generateMatrix();
        } else {
            setMatrix(null);
        }
    }, [selectedProducts, successfulActiveCount]);

    const toggleProductSelection = (product: string) => {
        setSelectedProducts(prev => 
            prev.includes(product) 
                ? prev.filter(p => p !== product)
                : [...prev, product]
        );
    };

    const selectAll = () => setSelectedProducts(allCatalogProducts);
    const deselectAll = () => setSelectedProducts([]);

    const generateMatrix = async () => {
        if (selectedProducts.length === 0) {
            setMatrix(null);
            return;
        }
        setIsCalculating(true);

        try {
            const archivedAnalyses = await getAnalyses();
            const allStores = await getStores();
            const storesMap = new Map<number, Store>(allStores.map(s => [s.id!, s]));

            // Mapa pre inventár predajní
            const storeInventory = new Map<string, { name: string, code?: string, products: Map<string, number> }>();

            // A. PRE-FILL: Inicializácia predajní z DB
            allStores.forEach(store => {
                const uniqueKey = `ID_${store.id}`;
                storeInventory.set(uniqueKey, { 
                    name: store.name, 
                    code: store.code, 
                    products: new Map() 
                });
            });

            // Pomocná funkcia pre update inventára
            const updateInventory = (inventory: { products: Map<string, number> }, products: DetectedProduct[]) => {
                products.forEach(p => {
                    if (!p || !p.name) return;
                    // V OSA reportoch ignorujeme produkty s veľmi nízkou istotou (pod 60%)
                    if (p.confidence < 0.6) return;

                    // Hľadáme zhodu v našom výbere
                    const matchedName = findBestMatch(p.name, selectedProducts);
                    if (matchedName) {
                        const currentMax = inventory.products.get(matchedName) || 0;
                        inventory.products.set(matchedName, Math.max(currentMax, p.confidence));
                    }
                });
            };

            // B. LIVE DATA: Aktuálna návšteva
            activeImages.forEach(img => {
                if (img.status !== 'success' || !img.analysisResult) return;

                let uniqueKey = '';
                if (img.assignedStoreId) {
                    uniqueKey = `ID_${img.assignedStoreId}`;
                } else if (img.analysisResult.storeInfo) {
                    const chain = removeDateFromStoreName(img.analysisResult.storeInfo.chain);
                    uniqueKey = `RAW_${chain}`;
                }

                if (!uniqueKey) return;

                if (!storeInventory.has(uniqueKey)) {
                    storeInventory.set(uniqueKey, { 
                        name: uniqueKey.replace('RAW_', '').replace('ID_', 'Predajňa #'), 
                        products: new Map() 
                    });
                }

                updateInventory(storeInventory.get(uniqueKey)!, img.analysisResult.products);
            });

            // C. ARCHIVE DATA: Staršie návštevy
            archivedAnalyses.forEach(analysis => {
                analysis.images.forEach(img => {
                    if (!img.analysisResult) return;

                    let uniqueKey = '';
                    if (img.assignedStoreId) {
                        uniqueKey = `ID_${img.assignedStoreId}`;
                    } else if (img.analysisResult.storeInfo) {
                        const chain = removeDateFromStoreName(img.analysisResult.storeInfo.chain);
                        uniqueKey = `RAW_${chain}`;
                    }

                    if (!uniqueKey || !storeInventory.has(uniqueKey)) return;
                    updateInventory(storeInventory.get(uniqueKey)!, img.analysisResult.products);
                });
            });

            // D. Konštrukcia riadkov pre tabuľku
            const rows: DistributionRow[] = [];
            const columnCounts: Record<string, number> = {};
            selectedProducts.forEach(p => columnCounts[p] = 0);

            for (const [key, data] of storeInventory.entries()) {
                const presenceRecord: Record<string, DistributionCell> = {};
                let presentCount = 0;

                selectedProducts.forEach(targetProduct => {
                    const maxConfidence = data.products.get(targetProduct) || 0;
                    const isPresent = maxConfidence > 0;

                    presenceRecord[targetProduct] = { 
                        isPresent, 
                        count: isPresent ? 1 : 0, 
                        maxConfidence 
                    };

                    if (isPresent) {
                        presentCount++;
                        columnCounts[targetProduct]++;
                    }
                });

                const fulfillment = selectedProducts.length > 0 ? (presentCount / selectedProducts.length) * 100 : 0;

                // Pridáme riadok len ak má nejakú aktivitu alebo je to známa predajňa z DB
                if (presentCount > 0 || key.startsWith('ID_')) {
                    rows.push({
                        storeName: data.name,
                        storeId: key.startsWith('ID_') ? parseInt(key.split('_')[1]) : undefined,
                        storeCode: data.code,
                        presence: presenceRecord,
                        totalFacings: presentCount,
                        fulfillment
                    });
                }
            }

            // Zoradenie: Najprv predajne s najvyšším plnením
            rows.sort((a, b) => b.fulfillment - a.fulfillment || a.storeName.localeCompare(b.storeName));

            // Výpočet podielu distribúcie (stĺpcové súhrny)
            const columnSummaries: Record<string, number> = {};
            const totalRowsWithData = rows.filter(r => r.totalFacings > 0).length || rows.length;

            selectedProducts.forEach(p => {
                columnSummaries[p] = totalRowsWithData > 0 ? (columnCounts[p] / totalRowsWithData) * 100 : 0;
            });

            setMatrix({ 
                rows, 
                columnSummaries, 
                selectedEntities: selectedProducts, 
                mode: 'sku' 
            });
        } catch (error) {
            console.error("Distribution calculation error:", error);
        } finally {
            setIsCalculating(false);
        }
    };

    const handleExport = () => {
        if (matrix) exportDistributionToXLS(matrix, t);
    };

    const openSaveModal = () => {
        const today = new Date();
        const defaultName = `${t('distributionModule')} - ${today.getDate()}.${today.getMonth() + 1}.${today.getFullYear()}`;
        setNewReportName(defaultName);
        setIsSaveModalOpen(true);
    };

    const handleSaveReport = async () => {
        if (!newReportName.trim()) return;
        await saveDistributionReport({
            name: newReportName.trim(),
            createdAt: new Date().toISOString(),
