                            <TableCellsIcon className="w-6 h-6 text-lime-600" />
                        </div>
                        {t('distributionModule')}
                    </h2>
                    {isAnyActiveAnalyzing && (
                        <div className="flex items-center gap-2 mt-2 text-xs font-bold text-lime-600 bg-lime-50 px-3 py-1 rounded-full w-fit animate-pulse">
                            <SpinnerIcon className="w-3 h-3" />
                            Prebieha analýza nových fotiek...
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap gap-3">
                    <button 
                        onClick={openLoadModal} 
                        className="flex items-center gap-2 px-5 py-2.5 text-sm font-black uppercase tracking-widest rounded-xl bg-gray-100 text-gray-700 hover:bg-gray-200 transition-all active:scale-95"
                    >
                        <FolderOpenIcon className="w-4 h-4" /> {t('savedReports')}
                    </button>
                    {selectedProducts.length > 0 && (
                        <button 
                            onClick={openSaveModal} 
                            className="flex items-center gap-2 px-5 py-2.5 text-sm font-black uppercase tracking-widest rounded-xl bg-gray-100 text-gray-700 hover:bg-gray-200 transition-all active:scale-95"
                        >
                            <SaveIcon className="w-4 h-4" /> {t('saveReport')}
                        </button>
                    )}
                    {matrix && (
                         <button 
                            onClick={handleExport} 
                            className="flex items-center gap-2 px-5 py-2.5 text-sm font-black uppercase tracking-widest rounded-xl bg-blue-600 text-white hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all active:scale-95"
                        >
                            <ArrowDownTrayIcon className="w-4 h-4" /> {t('exportToXLS')}
                        </button>
                    )}
                </div>
            </div>

            {/* Product Selection Area */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] flex items-center gap-2">
