                                            <button onClick={() => handleDeleteReport(report.id)} className="p-2 text-red-600 bg-red-50 rounded-xl hover:bg-red-100 transition-colors"><TrashIcon className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                     </div>
                </div>
            )}
        </div>
    );
};

