           activeView === 'analyses' ? <AnalysesPanel onNewAnalysis={() => setIsNewAnalysisModalOpen(true)} onLoadAnalysis={handleLoadAnalysis} /> :
           activeView === 'stores' ? <StoresPanel /> :
