export const ListingPanel: React.FC = () => {
    const { t } = useTranslation();
    const [entries, setEntries] = useState<ProductCatalogEntry[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [isTraining, setIsTraining] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    // Form State
    const [currentId, setCurrentId] = useState<number | undefined>(undefined);
    const [formData, setFormData] = useState({
        manufacturer: '',
        productName: '',
        sku: '',
        category: '',
    });
    const [aliases, setAliases] = useState<string[]>([]);
    const [currentAliasInput, setCurrentAliasInput] = useState('');
    const [uploadedImages, setUploadedImages] = useState<string[]>([]); // Base64 strings
    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        loadEntries();
    }, []);

    const loadEntries = async () => {
        setIsLoading(true);
        const data = await getCatalogEntries();
        setEntries(data.sort((a, b) => a.canonicalName.localeCompare(b.canonicalName)));
        setIsLoading(false);
    };

    const resetForm = () => {
        setFormData({ manufacturer: '', productName: '', sku: '', category: '' });
        setAliases([]);
        setCurrentAliasInput('');
        setUploadedImages([]);
        setCurrentId(undefined);
        setIsEditing(false);
    };

    const handleEdit = (entry: ProductCatalogEntry) => {
        setFormData({
            manufacturer: entry.manufacturer || '',
            productName: entry.canonicalName,
            sku: entry.sku || '',
            category: entry.category || '',
        });
        setAliases(entry.aliases || []);
        setUploadedImages(entry.referenceImages || []);
        setCurrentId(entry.id);
        setIsEditing(true);
    };

    const handleDelete = async (id: number) => {
        if (window.confirm(t('deleteProductConfirm'))) {
            await deleteCatalogEntry(id);
            loadEntries();
        }
    };

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setIsLoading(true);
            const newImages: string[] = [];
            for (let i = 0; i < e.target.files.length; i++) {
                try {
                    const compressedFile = await resizeAndCompressImage(e.target.files[i]);
                    const base64 = await fileToBase64(compressedFile);
                    newImages.push(base64);
                } catch (err) {
                    console.error("Error processing image:", err);
                }
            }
            setUploadedImages(prev => [...prev, ...newImages]);
            setIsLoading(false);
