                                    </tr>
                                ))}
                            </tbody>
                            <tfoot className="bg-gray-50 border-t-2 border-gray-100">
                                <tr className="font-black">
                                    <td className="px-6 py-5 text-[10px] uppercase font-black text-gray-400 sticky left-0 bg-gray-50 border-r border-gray-100">
                                        {t('distributionShare')}
                                    </td>
                                    {matrix.selectedProducts.map(p => (
                                        <td key={p} className="px-3 py-5 text-center text-xs text-lime-600 border-l border-gray-100">
