                                </tr>
                            </tfoot>
                        </table>
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center py-32 text-center">
                        <div className="p-6 bg-gray-50 rounded-full mb-6">
                            <TableCellsIcon className="w-16 h-16 text-gray-200" />
