import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { getAnalyses, getCatalogProductNames, saveDistributionReport, getDistributionReports, deleteDistributionReport, getStores } from '../db.ts';
import { DetectedProduct, DistributionMatrix, DistributionRow, DistributionReport, DistributionCell, Store } from '../types.ts';
import { normalizeProductName, removeDateFromStoreName, findBestMatch } from '../utils/helpers.ts';
import { exportDistributionToXLS } from '../utils/export.ts';
